public class ReportManager
{
    public string Generate(int type, List<Sale> sales, bool sendEmail, bool saveToDisk)
    {
        string result = "";
        if (type == 1)
            foreach (var s in sales) result += s.Amount + ";";
        else if (type == 2)
            foreach (var s in sales) result += "<td>" + s.Amount + "</td>";

        if (sendEmail)
        {
            var smtp = new SmtpClient("smtp.company.com");
            smtp.Send("reports@company.com", "boss@company.com", "Report", result);
        }
        if (saveToDisk)
            File.WriteAllText("C:\\reports\\r.txt", result);
        return result;
    }
}

